// What does a read filter answering PSFS_ERR_FATAL do to each reader?
class FatalFilter extends php_user_filter {
    public function filter($in, $out, &$consumed, $closing): int
    {
        stream_bucket_make_writeable($in);
        return PSFS_ERR_FATAL;
    }
}
stream_filter_register('fatalf', FatalFilter::class);

function src(): mixed {
    $s = fopen('php://memory', 'rb+');
    fwrite($s, 'Test data');
    rewind($s);
    stream_filter_prepend($s, 'fatalf', STREAM_FILTER_READ);
    return $s;
}

